import {PERSONAS,clone,diff,fieldLabel,filterUnits,parsePhone,prettyPhone,reconcile} from './model.js';
import {icon} from './icons.js';
const concepts={
  relay:{name:'Relay',tag:'A shared line of sight.',description:'A calm team workspace. Keep the record, the evidence, and the conversation within reach.',number:'01',inspiration:'Fluent-inspired',words:['Record workspace','Evidence rail','Contextual copilot']},
  atelier:{name:'Atelier',tag:'Space to see the whole story.',description:'A contact becomes a living folio. Fluid sheets, a revision filmstrip, and an assistant that comes to you.',number:'02',inspiration:'Apple-inspired',words:['Living folio','Revision filmstrip','Floating assistant']},
  trace:{name:'Trace',tag:'Follow the change. Find the why.',description:'An editorial evidence board for shared investigation. Connect decisions without losing their source.',number:'03',inspiration:'Editorial canvas',words:['Evidence board','Actor lanes','Working theory']}
};
const variant=location.pathname.split('/')[1];
const root=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey=`overmind-b:${variant}`;
const s={variant,page:'contact',contact:'lina',persona:new URLSearchParams(location.search).get('persona')||sessionStorage.getItem(storageKey+':persona')||'Mariana',theme:localStorage.getItem(storageKey+':theme')||'light',db:null,draft:null,base:null,editing:false,section:'all',selectedRev:null,compare:null,historyMode:'diff',unit:null,filters:JSON.parse(sessionStorage.getItem(storageKey+':filters')||'{}'),assistant:variant!=='atelier'&&innerWidth>1050,answer:null,proposal:false,conflict:null,choices:{},demo:false,condition:'normal',uncertain:false,busy:false,toast:null,peers:{},pendingNav:null};
if(!PERSONAS[s.persona])s.persona='Mariana';
let channel;
let tabId=crypto.randomUUID();
let toastTimer;
const can=()=>PERSONAS[s.persona];
const contact=()=>s.db.contacts[s.contact];
const revisions=()=>s.db.revisions[s.contact]||[];
const unitFor=(id,rev)=>s.db.units.find(u=>u.contact===id&&u.revision===rev);
const button=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(label,cls='')=>`<span class="tag ${cls}">${label}</span>`;
const stampTime=time=>new Intl.DateTimeFormat('en',{timeZone:'America/Mexico_City',hour:'numeric',minute:'2-digit'}).format(new Date(time));
const stampDate=time=>new Intl.DateTimeFormat('en',{timeZone:'America/Mexico_City',month:'short',day:'numeric'}).format(new Date(time));
const avatar=(name,size='')=>`<span class="avatar ${size} ${name==='Bruno'?'bruno':name==='Isabel'?'isabel':name==='Rafael'?'rafael':''}" aria-hidden="true">${name==='Directory viewer'?'DV':name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>`;
const logo=()=>`<span class="logo-mark" aria-hidden="true"><span></span><span></span><span></span></span>`;
function gallery(){
  document.title='Overmind · Three ways to work together';
  document.body.className='gallery-body';
  root.innerHTML=`<main id="main" class="gallery"><header>${logo()}<strong>overmind</strong><span class="gallery-label">DESIGN EXPLORATIONS / AGENT B</span></header><div class="gallery-heading"><p class="eyebrow">CONTACTS · CONTEXT · COLLABORATION</p><h1>Better work starts with<br><em>shared understanding.</em></h1><p>Three independent ways to edit a contact, explain a change,<br>and investigate together. Choose a workspace to explore.</p></div><div class="concept-grid">${Object.entries(concepts).map(([key,c])=>`<a class="concept-card ${key}-preview" href="/${key}"><div class="concept-preview"><div class="mini-toolbar"><i></i><i></i><i></i></div><div class="mini-art"><div class="mini-nav"></div><div class="mini-main"><div class="mini-avatar">LT</div><b>Lina Torres</b><span></span><span></span><span></span></div><div class="mini-aside"><i></i><i></i><i></i></div></div><span class="preview-label">${c.inspiration}</span></div><div class="concept-copy"><span class="eyebrow">EXPLORATION ${c.number}</span><h2>${c.name} ${icon('arrow')}</h2><h3>${c.tag}</h3><p>${c.description}</p><div class="concept-words">${c.words.map(w=>`<span>${w}</span>`).join('')}</div></div></a>`).join('')}</div><footer><span>Vértice Demo · Fictional data · Runs entirely on your machine</span><a href="/README.md">Demo guide & capability map ${icon('arrow')}</a></footer></main>`;
}
async function api(path,data){
  const response=await fetch(`/_demo/${path}?variant=${variant}&persona=${encodeURIComponent(s.persona)}`,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});
  const result=await response.json();return {...result,status:response.status};
}
async function refresh(){s.db=await api('state');if(!s.db.contacts)throw new Error('The local demo server is unavailable.');}
function notify(message){s.toast=message;clearTimeout(toastTimer);render();toastTimer=setTimeout(()=>{s.toast=null;document.querySelector('.toast')?.remove();},5500);}
function broadcast(type='change'){channel?.postMessage({type,tabId,contact:s.contact,persona:s.persona,section:s.editing?s.section:'viewing',time:Date.now()});}
function readRoute(){const [page,id,rev]=location.hash.slice(1).split('/');if(['contact','history','activity'].includes(page))s.page=page;if(['lina','norte'].includes(id))s.contact=id;if(page==='history'&&rev)s.selectedRev=Number(rev);}
function route(page,id=s.contact,rev=null,writeHistory=true){
  if(s.draft&&id!==s.contact){s.pendingNav={page,id,rev};render();return;}
  s.page=page;s.contact=id;if(rev){s.selectedRev=Number(rev);s.compare=Math.max(1,s.selectedRev-1);s.historyMode='diff';}
  s.condition=s.condition==='loading'?'normal':s.condition;
  if(writeHistory)history.pushState(null,'',`/${variant}${location.search}#${page}/${id}${rev?'/'+rev:''}`);
  broadcast('presence');render();document.querySelector('#main')?.focus({preventScroll:true});
}
function startEdit(section='all'){
  if(!can().edit){notify('This persona can read evidence, but cannot edit contacts.');return;}
  if(s.uncertain){notify('Investigate the previous Save before starting another edit.');return;}
  if(!s.draft){s.base=clone(contact());s.draft=clone(contact());}
  s.editing=true;s.section=section;s.page='contact';broadcast('presence');render();document.querySelector('.editor input')?.focus();
}
function discard(){s.draft=null;s.base=null;s.editing=false;s.conflict=null;s.proposal=false;s.answer=null;broadcast('presence');}
function orderPrimary(family,ordinal){const list=s.draft[family].filter(x=>!x.deleted).sort((a,b)=>a.order-b.order);const moved=list.find(x=>x.ordinal===ordinal);list.splice(list.indexOf(moved),1);list.unshift(moved);list.forEach((x,i)=>x.order=i+1);}
function nav(){return `<nav class="main-nav" aria-label="Workspace">${[['contact','people','Contacts','Record'],['history','history','Contact history','Evidence'],['activity','activity','Tenant activity','Activity']].map(([page,i,label,short],index)=>button(`${variant==='trace'?`<span class="nav-index">0${index+1}</span>`:icon(i)}<span>${variant==='trace'?short:label}</span>${page==='contact'&&variant==='relay'?'<span class="nav-count">2</span>':''}`,`nav-${page}`,s.page===page?'active':'',s.page===page?'aria-current="page"':'')).join('')}</nav>`;}
function header(){return `<header class="topbar"><a class="brand" href="/" aria-label="Overmind concept gallery">${logo()}<strong>overmind</strong><span class="concept-name">${concepts[variant].name}</span></a>${variant==='atelier'?nav():`<div class="topbar-location">Vértice Demo <span>/</span> ${s.page==='activity'?'Activity & evidence':'Contact workspace'}</div>`}<div class="topbar-tools">${button(icon('sparkle')+'<span>Sidekick</span>','assistant','subtle assistant-trigger','aria-label="Sidekick" aria-expanded="'+s.assistant+'"')}${button(icon(s.theme==='dark'?'sun':'moon'),'theme','icon-btn',`aria-label="Switch to ${s.theme==='dark'?'light':'dark'} mode"`)}<span class="divider"></span>${avatar(s.persona)}<span class="persona-top">${esc(s.persona)}<small>${can().role}</small></span></div></header>`;}
function sidebar(){return `<aside class="sidebar"><div class="tenant-card"><span class="tenant-icon">V</span><div><b>Vértice Demo</b><small>Team workspace</small></div>${icon('chevron')}</div><span class="nav-caption">WORKSPACE</span>${nav()}<div class="sidebar-contacts"><span class="nav-caption">IN THIS WORKSPACE</span>${['lina','norte'].map(id=>button(`${id==='lina'?avatar('Lina Torres','small'):icon('building')}<span>${id==='lina'?'Lina Torres':'Norte Taller'}</span>`,`contact-${id}`,s.contact===id?'selected':'')).join('')}</div><div class="sidebar-foot"><div class="live-dot"></div><span>Local demo connected<small>Changes stay on this machine</small></span></div></aside>`;}
function presence(){const peers=Object.values(s.peers).filter(p=>p.contact===s.contact&&Date.now()-p.time<18000);return `<div class="presence"><div class="avatar-stack">${avatar(s.persona,'tiny')}${peers.map(p=>avatar(p.persona,'tiny')).join('')}</div><div><b>${peers.length?peers.map(p=>esc(p.persona)).join(', '):'Your shared workspace'}</b><small>${peers.length?peers.map(p=>`${esc(p.persona)} · ${p.section==='viewing'?'viewing':`editing ${esc(p.section)}`}`).join(' / '):'Open a second tab to work together'}</small></div><span class="presence-dot" title="Presence is awareness, not a database lock"></span></div>`;}
function breadcrumbs(){return `<div class="breadcrumbs"><span>Workspace</span>${icon('chevron')}<button data-action="nav-contact">Contacts</button>${icon('chevron')}<span>${s.contact==='lina'?'Lina Torres':'Norte Taller'}</span>${s.page==='history'?`${icon('chevron')}<b>History</b>`:''}</div>`;}
function contactSwitch(){return `<label class="contact-switch"><span class="sr-only">Choose contact</span><select id="contact-select"><option value="lina" ${s.contact==='lina'?'selected':''}>Lina Torres · Person</option><option value="norte" ${s.contact==='norte'?'selected':''}>Norte Taller · Organization</option></select></label>`;}
function contactHeading(){const c=contact();return `<div class="record-heading"><div class="record-title">${s.contact==='lina'?avatar('Lina Torres','portrait'):`<span class="avatar portrait organization">${icon('building')}</span>`}<div><div class="heading-meta">${tag(c.category)}<span class="quiet">Contact workspace</span></div><h1>${esc(c.name)}</h1><p>${variant==='trace'?'Every detail has a story. Keep the evidence close.':s.contact==='lina'?'A shared view of the details that matter.':'An independent organization contact.'}</p><div class="record-meta">${tag('Active','green')}<span>Revision ${c.revision}</span><span class="dot-separator">·</span><span>Vértice Demo</span></div></div></div><div class="heading-actions">${contactSwitch()}${can().edit?button(icon('edit')+(variant==='atelier'?'Edit folio':'Edit contact'),'edit-all','primary'):tag('Read-only','neutral')}</div></div>`;}
function channels(family,{historical=null}={}){const c=historical||contact();const list=c[family].filter(x=>!x.deleted).sort((a,b)=>a.order-b.order);const names={email:'Email addresses',phone:'Phone numbers',address:'Mailing address'};return `<section class="channel-group ${family}" aria-label="${names[family]}"><div class="section-header"><h2>${icon(family==='address'?'pin':family==='email'?'mail':'phone')}${names[family]}${family!=='address'?`<span class="count">${list.length}</span>`:''}</h2>${!historical&&can().edit?button(family==='address'?icon('edit')+'Edit':icon('plus')+'Add',`add-${family}`,'text-btn'):''}</div><div class="channel-list">${list.map(item=>`<div class="channel-row" data-channel="${family}-${item.ordinal}"><span class="channel-glyph">${icon(family==='address'?'pin':family==='email'?'mail':'phone')}</span><div class="channel-value"><strong>${esc(family==='phone'?prettyPhone(item.value):item.value)}</strong><div class="channel-metadata"><span>${esc(item.label||'Unlabeled')}</span>${family==='phone'&&item.extension?`<span>Ext. ${esc(item.extension)}</span>`:''}<span class="visibility">${icon(item.public?'globe':'lock')}${item.public?'Public':'Private'}</span>${item.order===1?tag('Primary','primary-tag'):`<span class="order-label">Position ${item.order}</span>`}</div></div>${!historical&&can().edit?`<div class="row-tools">${item.order!==1&&family!=='address'?button(icon('star'),`primary-${family}-${item.ordinal}`,'icon-btn',`aria-label="Make ${esc(item.label)} ${family} primary"`):''}${button(icon('edit'),`edit-${family}`,'icon-btn',`aria-label="Edit ${esc(item.label)} ${family}"`)}</div>`:''}</div>`).join('')||'<p class="empty-inline">No public channels in this family.</p>'}</div>${family==='email'?'<p class="section-note">Primary follows saved order. Reordering keeps each address’s identity.</p>':family==='address'?'<p class="section-note">A correction updates this contact’s mailing address only.</p>':''}</section>`;}
function recentEvidence(){const units=s.db.units.filter(u=>u.contact===s.contact).sort((a,b)=>b.revision-a.revision).slice(0,3);return `<section class="recent-evidence"><div class="section-header"><h2>${icon('history')}${variant==='trace'?'The trail of decisions':'Recent changes'}</h2>${button('View all '+icon('arrow'),'nav-history','text-btn')}</div>${units.map((u,i)=>`<button class="evidence-item" data-action="revision-${u.revision}"><span class="evidence-node">${i===0?icon('check'):icon(u.actions[0].family==='phone'?'phone':'history')}</span><span><strong>${esc(u.title)}</strong><small>${esc(u.actor)} · ${stampDate(u.time)} · Revision ${u.revision}</small>${variant==='trace'?`<span class="evidence-excerpt">First action: ${esc(u.actions[0].field)} <b>→</b> ${esc(u.actions[0].after)}</span>`:''}</span>${icon('chevron')}</button>`).join('')||'<p class="section-note">History is not available to a directory persona.</p>'}</section>`;}
function contextNote(){return `<div class="context-note">${icon('link')}<div><b>Related context, clear boundaries</b><p>Lina and Norte Taller are separate contacts. Appearing together does not establish an employment relationship.</p>${button('Open '+(s.contact==='lina'?'Norte Taller':'Lina Torres')+' '+icon('arrow'),'contact-'+(s.contact==='lina'?'norte':'lina'),'text-btn')}</div></div>`;}
function contactPage(){
  if(s.condition==='loading')return stateScreen('loading');
  if(s.condition==='denied')return stateScreen('denied');
  const core=`${channels('email')}${channels('phone')}${channels('address')}`;
  if(variant==='relay')return `${breadcrumbs()}${contactHeading()}${presence()}<div class="relay-record"><div class="record-fields">${s.editing?editor():core}</div><div class="record-margin">${recentEvidence()}${contextNote()}<div class="quiet-card">${icon('layers')}<b>One thoughtful Save.</b><p>Change a name, a number, and an address. They become one revision, saved together.</p>${can().edit?button('Start a combined edit '+icon('arrow'),'edit-all','text-btn'):''}</div></div></div>`;
  if(variant==='atelier')return `<div class="atelier-overline"><span>YOUR CONTACT FOLIO</span>${presence()}</div>${contactHeading()}<div class="folio-layout"><div class="folio-summary"><div class="folio-monogram">${s.contact==='lina'?'lt.':'nt.'}<span class="monogram-ring"></span></div><p class="eyebrow">${contact().category.toUpperCase()} / VÉRTICE DEMO</p><h2>Details, with <br>room to breathe.</h2><p>Reach the right person.<br>Understand how you got here.</p>${button(icon('history')+' Explore the timeline','nav-history','secondary')}${contextNote()}</div><div class="folio-channels">${core}</div></div><div class="folio-recent">${recentEvidence()}</div>${s.editing?`<div class="sheet-backdrop"><section class="edit-sheet" role="dialog" aria-modal="true" aria-label="Edit contact folio">${editor()}</section></div>`:''}`;
  return `<div class="trace-title"><div><p class="eyebrow">CASE NOTES / ${s.contact==='lina'?'001':'002'}</p><h1>${esc(contact().name)}<span class="serif-dot">.</span></h1><p>A contact. A trail of decisions. A shared understanding.</p></div><div>${contactSwitch()}${presence()}</div></div><div class="trace-board"><section class="board-record"><div class="board-label"><span>01 / CURRENT RECORD</span>${tag('Revision '+contact().revision)}</div>${can().edit?button(icon('edit')+'Edit contact','edit-all','primary board-edit'):tag('Read-only','neutral')}${s.editing?editor():core}${contextNote()}</section><div class="board-story"><div class="board-label"><span>02 / FOLLOW THE EVIDENCE</span>${icon('link')}</div>${recentEvidence()}<div class="paper-note"><span class="eyebrow">INVESTIGATION NOTE</span>${s.db.units.some(u=>u.id==='unit-lina-5')?`<h3>A change can leave<br>no final difference.</h3><p>Revision 5 changed an extension and changed it back. The two actions still tell a story.</p>${button('Inspect the two actions '+icon('arrow'),'roundtrip','text-btn')}`:`<h3>Shared context.<br>Separate drafts.</h3><p>This is the conflict story. Each collaborator saves against an explicit revision. Restore the full demo story to investigate the change-and-change-back example.</p>`}</div></div></div>`;
}
function input(label,id,value,attrs=''){return `<label class="field"><span>${label}</span><input id="${id}" value="${esc(value)}" ${attrs}></label>`;}
function editor(){const d=s.draft;if(!d)return '';const count=diff(s.base,d).length;return `<div class="editor"><div class="editor-title"><div><span class="eyebrow">${s.proposal?'SIDEKICK PROPOSAL':'YOUR PRIVATE DRAFT'}</span><h2>${s.section==='all'?'Edit contact details':`Edit ${s.section==='email'?'email addresses':s.section==='phone'?'phone numbers':'mailing address'}`}</h2></div>${button(icon('close'),'cancel','icon-btn','aria-label="Cancel editing"')}</div><p class="editor-subtitle">Based on revision ${s.base.revision}. All changes use one Save.</p>${s.proposal?`<div class="proposal-banner">${icon('sparkle')}<span>Extension → 25 · Work email → Primary.<br><small>Review or adjust the fields below before saving.</small></span></div>`:''}<div id="validation-errors" role="alert"></div><form id="edit-form" novalidate>${s.section==='all'?input('Full name','edit-name',d.name,'maxlength="256" autocomplete="off"'):''}${['email','phone','address'].filter(f=>s.section==='all'||s.section===f).map(f=>`<fieldset><legend>${f==='email'?'Email addresses':f==='phone'?'Phone numbers':'Mailing address'}</legend>${d[f].filter(x=>!x.deleted).sort((a,b)=>a.order-b.order).map(x=>`<div class="edit-child"><div class="edit-child-heading"><b>${esc(x.label||'New '+f)}</b>${x.order===1?tag('Primary','primary-tag'):tag('Position '+x.order)}</div>${f==='address'?`<label class="field"><span>Mailing address</span><textarea id="edit-address-${x.ordinal}-value" rows="3">${esc(x.value)}</textarea></label>`:input(f==='phone'?'Phone number':'Email address',`edit-${f}-${x.ordinal}-value`,f==='phone'?prettyPhone(x.value):x.value,f==='email'?'type="email" autocomplete="off"':'type="tel"')}<div class="form-grid">${input('Label',`edit-${f}-${x.ordinal}-label`,x.label,'maxlength="100"')}${f==='phone'?input('Extension',`edit-phone-${x.ordinal}-extension`,x.extension,'maxlength="10" inputmode="numeric"'):''}<label class="field"><span>Visibility</span><select id="edit-${f}-${x.ordinal}-public"><option value="true" ${x.public?'selected':''}>Public</option><option value="false" ${!x.public?'selected':''}>Private</option></select></label></div>${f==='phone'?`<details class="phone-context"><summary>Mexican local number context</summary><div class="form-grid">${input('Country / region',`edit-phone-${x.ordinal}-region`,x.region||'MX','maxlength="2"')}${input('Area code',`edit-phone-${x.ordinal}-area`,x.area||'777','maxlength="3" inputmode="numeric"')}</div><p>For 312 3456, MX + area 777 gives +52 777 312 3456. Numbering context does not tell us where this person lives.</p></details><p class="phone-interpretation" id="phone-hint-${x.ordinal}">${phoneHint(x)}</p>`:''}${f!=='address'&&x.order!==1&&x.ordinal>0?button(icon('star')+'Make primary',`draft-primary-${f}-${x.ordinal}`,'text-btn'):''}${x.ordinal<0?button('Remove unsaved item',`remove-${f}-${x.ordinal}`,'text-btn'):''}</div>`).join('')}${f!=='address'?button(icon('plus')+'Add '+f,`draft-add-${f}`,'secondary'):''}</fieldset>`).join('')}<div class="save-bar"><div><b id="draft-count">${count} pending ${count===1?'change':'changes'}</b><small>One Save · One revision</small></div>${button(s.proposal?'Discard proposal':'Cancel',s.proposal?'discard-proposal':'cancel','secondary')}${button(s.busy?'Saving…':s.proposal?'Apply & Save':'Save changes','save','primary',s.busy||s.uncertain?'disabled':'')}</div></form></div>`;}
function phoneHint(item){try{const parsed=parsePhone(item.value,item.region||'MX',item.area||'777');return `${icon('check')} Interpreted as ${esc(prettyPhone(parsed.number))} · ${esc(parsed.source)}`;}catch(e){return `${icon('info')} ${esc(e.message)}`;}}
function stateScreen(kind){const options={loading:['Opening the record','Gathering this contact’s current details and revision.','Continue to record','clear-condition','layers'],denied:['This view needs permission','Your persona does not have access to this view. Ask an administrator for the appropriate contact grant.','Return to contact','clear-condition','lock'],unavailable:['This part of the story is unavailable','Historical coverage is missing for this revision. Current values cannot fill in the gap.','Return to available history','clear-condition','history'],empty:['No changes match these filters','Try a different person, family, date range, or search term.','Clear filters','clear-filters','search']};const [title,body,label,action,i]=options[kind];return `<div class="state-screen ${kind}"><span class="state-icon">${icon(i)}</span><h2>${title}</h2><p>${body}</p>${kind==='loading'?'<div class="skeleton-lines"><i></i><i></i><i></i></div>':''}${button(label,action,'secondary')}</div>`;}
function revisionTabs(){return `<div class="segmented history-modes" role="group" aria-label="History presentation">${[['snapshot','State at revision'],['diff','Compare revisions'],['actions','Actions in Save']].map(([key,label])=>button(label,'history-mode-'+key,s.historyMode===key?'selected':'','aria-pressed="'+(s.historyMode===key)+'"')).join('')}</div>`;}
function diffTable(left,right){const changes=diff(left,right);return changes.length?`<div class="diff-table"><div class="diff-table-head"><span>FIELD</span><span>BEFORE · R${left.revision}</span><span>AFTER · R${right.revision}</span></div>${changes.map(d=>`<div class="diff-row" id="field-${d.key.replaceAll('.','-')}"><strong>${esc(d.label)}</strong><span class="before"><small>Before</small>${esc(d.before)}</span><span class="after"><small>After</small>${esc(d.after)}</span></div>`).join('')}</div>`:`<div class="equal-state">${icon('check')}<h3>No final differences</h3><p>These two revisions end in the same state. Actions can still explain what happened during the Save.</p>${button('See ordered actions '+icon('arrow'),'history-mode-actions','text-btn')}</div>`;}
function actionsList(unit){return `<ol class="actions-list">${unit.actions.map(a=>`<li><span class="action-number">${a.order}</span><div><div class="action-title"><strong>${esc(a.field)}</strong>${tag(a.kind,'neutral')}</div><div class="action-values"><span class="before"><small>Before</small>${esc(a.before)}</span>${icon('arrow')}<span class="after"><small>After</small>${esc(a.after)}</span></div></div></li>`).join('')}</ol>`;}
function technical(unit){return `<details class="technical"><summary>${icon('info')}Technical details</summary><dl><dt>Audit unit</dt><dd>${esc(unit.id)}</dd><dt>Audit stamp</dt><dd>${esc(unit.stamp)} <span>(Int64 string)</span></dd><dt>Source</dt><dd>Committed application activity</dd></dl><p>The stamp correlates this Save. It is not a universal snapshot or proof of commit order across contacts.</p></details>`;}
function historyPage(){
  if(!can().history||s.condition==='denied')return stateScreen('denied');
  if(s.condition==='unavailable')return stateScreen('unavailable');
  if(s.condition==='loading')return stateScreen('loading');
  const revs=revisions();if(!s.selectedRev||!revs.some(r=>r.revision===s.selectedRev))s.selectedRev=revs.at(-1).revision;
  if(!s.compare||!revs.some(r=>r.revision===s.compare))s.compare=Math.max(1,s.selectedRev-1);
  const selected=revs.find(r=>r.revision===s.selectedRev),prior=revs.find(r=>r.revision===s.compare),unit=unitFor(s.contact,selected.revision);
  const heading=`<div class="page-heading"><div><p class="eyebrow">${variant==='trace'?'02 / THE EVIDENCE':'CONTACT HISTORY'}</p><h1>${variant==='atelier'?'A story, revision by revision.':variant==='trace'?'What changed. What stayed.':'The story behind the details'}</h1><p>${esc(s.contact==='lina'?'Lina Torres':'Norte Taller')} · ${revs.length} revisions · Mexico City, UTC−06:00</p></div>${button(icon('back')+'Current contact','nav-contact','secondary')}</div>`;
  const revisionList=`<div class="revision-list">${[...revs].reverse().map(r=>{const u=unitFor(s.contact,r.revision);return `<button class="revision-option ${r.revision===s.selectedRev?'selected':''}" data-action="revision-${r.revision}" aria-pressed="${r.revision===s.selectedRev}"><span class="revision-number">${String(r.revision).padStart(2,'0')}</span><span><b>${esc(u.title)}</b><small>${esc(u.actor)} · ${stampDate(u.time)}</small></span>${icon('chevron')}</button>`;}).join('')}</div>`;
  const body=`<div class="history-document"><div class="readonly-banner">${icon('lock')}<b>Read-only history</b><span>Inspecting a revision does not undo it.</span></div><div class="revision-heading"><div><p class="eyebrow">REVISION ${selected.revision}</p><h2>${esc(unit.title)}</h2><p>Changed by <b>${esc(unit.actor)}</b> · ${stampDate(unit.time)} at ${stampTime(unit.time)} · UTC−06:00</p></div>${avatar(unit.actor)}</div>${revisionTabs()}${s.historyMode==='diff'?`<div class="comparison-toolbar"><span>Compare</span><label><span class="sr-only">From revision</span><select id="compare-from">${revs.map(r=>`<option value="${r.revision}" ${r.revision===s.compare?'selected':''}>Revision ${r.revision}</option>`).join('')}</select></label>${icon('arrow')}<label><span class="sr-only">To revision</span><select id="compare-to">${revs.map(r=>`<option value="${r.revision}" ${r.revision===s.selectedRev?'selected':''}>Revision ${r.revision}</option>`).join('')}</select></label><span class="quiet">${diff(prior.state,selected.state).length} final differences</span></div>${diffTable(prior.state,selected.state)}`:s.historyMode==='snapshot'?`<div class="historical-profile"><span class="eyebrow">STATE AT REVISION ${selected.revision}</span><h3>${esc(selected.state.name)}</h3><p>${selected.state.category} · Historical labels and saved order</p></div>${channels('email',{historical:selected.state})}${channels('phone',{historical:selected.state})}${channels('address',{historical:selected.state})}`:`<div class="action-intro"><h3>${unit.actions.length} ordered actions · Saved together</h3><p>Effective business changes in this Save, including values changed back before commit.</p></div>${actionsList(unit)}`}<div class="unit-reference">${icon('layers')}<div><b>One shared audit unit</b><small>${unit.actions.length} actions · ${esc(unit.actor)} · Revision ${unit.revision}</small></div>${button('Open audit unit '+icon('arrow'),'unit-'+unit.id,'text-btn')}</div>${technical(unit)}</div>`;
  return `${variant==='relay'?breadcrumbs():''}${heading}<div class="history-layout">${revisionList}${body}</div>`;
}
function filters(){return `<div class="activity-filters"><label class="search-field">${icon('search')}<input id="activity-search" type="search" placeholder="Search changes, values, or people…" value="${esc(s.filters.search||'')}" aria-label="Search activity"></label>${[['actor','Actor',['Mariana','Bruno','Isabel']],['contact','Contact',['lina','norte']],['family','Family',['profile','email','phone','address']],['range','Time range',['week','today']]].map(([key,label,values])=>`<label class="filter-select"><span class="sr-only">${label}</span><select id="filter-${key}"><option value="">${label==='Time range'?'All dates':label==='Family'?'All families':'All '+label.toLowerCase()+'s'}</option>${values.map(v=>`<option value="${v}" ${s.filters[key]===v?'selected':''}>${{lina:'Lina Torres',norte:'Norte Taller',week:'This week',today:'Today',profile:'Profile',email:'Email',phone:'Phone',address:'Address'}[v]||v}</option>`).join('')}</select></label>`).join('')}${button(icon('close'),'clear-filters','icon-btn','aria-label="Clear all activity filters"')}</div>`;}
function unitDetail(unit){return `<div class="unit-detail"><div class="unit-detail-top"><span class="eyebrow">AUDIT UNIT / COMMITTED</span>${button(icon('close'),'close-unit','icon-btn','aria-label="Close audit unit"')}</div><h2>${esc(unit.title)}</h2><div class="unit-person">${avatar(unit.actor)}<div><b>${esc(unit.actor)}</b><small>${stampDate(unit.time)} · ${stampTime(unit.time)} · UTC−06:00</small></div></div><div class="unit-record"><span>AFFECTED CONTACT</span><b>${unit.contact==='lina'?'Lina Torres':'Norte Taller'} ${tag('Revision '+unit.revision)}</b>${button('Open revision & comparison '+icon('arrow'),'evidence-'+unit.contact+'-'+unit.revision,'text-btn')}</div><h3>Saved together · ${unit.actions.length} actions</h3>${actionsList(unit)}${technical(unit)}</div>`;}
